class Solution {
  public List<String> ambiguousCoordinates(String s) {
    String digits = s.substring(1, s.length() - 1);
    List<String> answer = new ArrayList<>();
    for (int split = 1; split < digits.length(); split++) {
      List<String> left = numbers(digits.substring(0, split));
      List<String> right = numbers(digits.substring(split));
      for (String a : left) {
        for (String b : right) answer.add("(" + a + ", " + b + ")");
      }
    }
    return answer;
  }

  // every valid way to write the digit string as an integer or a decimal
  private List<String> numbers(String s) {
    List<String> result = new ArrayList<>();
    if (s.length() == 1 || s.charAt(0) != '0') result.add(s);
    if (s.charAt(s.length() - 1) != '0') {
      for (int i = 1; i < s.length(); i++) {
        String whole = s.substring(0, i);
        if (whole.length() > 1 && whole.charAt(0) == '0') continue;
        result.add(whole + "." + s.substring(i));
      }
    }
    return result;
  }
}
